              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^MODEL-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "architecture"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^ARCH-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "quality_policy"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^POLICY-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "domain_alignment"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^ALIGNMODEL-[0-9A-F]{16}$"
                  }
                }
              }
            }
          ]
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "action": {
                "const": "move"
              }
            }
          },
          "then": {
            "required": [
              "to_path"
            ]
          },
          "else": {
            "not": {
              "required": [
                "to_path"
              ]
            }
          }
        }
      ]
    },
    "adr_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "disposition",
        "reason",
        "evidence_refs"
      ],
      "properties": {
        "disposition": {
          "enum": [
            "create",
            "update",
            "not_required"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "artifact_id": {
          "type": "string",
          "minLength": 1
        },
        "path": {
          "type": "string",
          "minLength": 1
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "disposition": {
                "enum": [
                  "create",
                  "update"
                ]
              }
            }
          },
          "then": {
            "required": [
              "artifact_id",
              "path"
            ]
          },
          "else": {
            "not": {
              "anyOf": [
                {
                  "required": [
                    "artifact_id"
                  ]
                },
                {
                  "required": [
                    "path"
                  ]
                }
              ]
            }
          }
        }
      ]
    },
    "verification_command": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "argv",
        "cwd",
        "run_kind",
        "covers",
        "reason"
      ],
      "properties": {
        "argv": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "cwd": {
          "type": "string",
          "minLength": 1
        },
        "run_kind": {
          "enum": [
            "targeted_test",
            "integration_test",
            "acceptance_test",
            "typecheck",
            "build",
            "lint",
            "manual_check",
            "full_regression"
          ]
        },
        "covers": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "pattern": "^(direction\\.acceptance:DIRACC-[0-9A-F]{16}|direction\\.constraint:DIRCON-[0-9A-F]{16}|direction\\.example:DIREX-[0-9A-F]{16}|risk_assessments\\[[0-9]+\\])$"
          }
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "optional_timeout": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 3600
        },
        "case_report": {
          "$ref": "test-case-config-v1.schema.json#/$defs/config"
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        },
        "input_repository_ids": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        },
        "dependency_checks": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "dependency_id",
              "kind",
              "expected_version",
              "expected_contract_sha256",
              "environment",
              "max_age_seconds"
            ],
            "properties": {
              "dependency_id": {
                "type": "string",
                "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
              },
              "kind": {
                "enum": [
                  "service",
                  "artifact"
                ]
              },
              "expected_version": {
                "type": "string",
                "minLength": 1
              },
              "expected_contract_sha256": {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              "environment": {
                "type": "string",
                "minLength": 1
              },
              "max_age_seconds": {
                "type": [
                  "integer",
                  "null"
                ],
                "minimum": 1,
                "maximum": 604800
              }
            }
          }
        }
      }
    },
    "external_observation_provider_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "provider_plan_id",
        "scope_id",
        "language_id",
        "provider_id",
        "provider_version",
        "command",
        "materials",
        "source_globs",
        "process_policy",
        "limits"
      ],
      "properties": {
        "provider_plan_id": {
          "type": "string",
          "pattern": "^OBSPROVPLAN-[0-9A-F]{16}$"
        },
        "scope_id": {
          "type": "string",
          "pattern": "^OBSCOPE-[0-9A-F]{16}$"
        },
        "language_id": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9+.#_-]*$"
        },
        "provider_id": {
          "type": "string",
          "minLength": 1
        },
        "provider_version": {
          "type": "string",
          "minLength": 1
        },
        "command": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "materials": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/external_observation_provider_material"
          }
        },
        "source_globs": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "process_policy": {
          "$ref": "#/$defs/external_observation_process_policy"
        },
        "limits": {
          "$ref": "#/$defs/external_observation_limits"
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        }
      }
    },
    "external_observation_provider_material": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "role",
        "path",
        "sha256",
        "command_argument_index"
      ],
      "properties": {
        "role": {
          "enum": [
            "executable",
            "entry_script",
            "config",
            "supporting_file"
          ]
        },
        "path": {
          "type": "string",
          "minLength": 1
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "command_argument_index": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        }
      }
    },
    "external_observation_process_policy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "policy_id",
        "purpose",
        "forbidden_program_names"
      ],
      "properties": {
        "policy_id": {
          "type": "string",
          "pattern": "^PROCESSPOLICY-[0-9A-F]{16}$"
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "forbidden_program_names": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "external_observation_limits": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "timeout_seconds",
        "cleanup_timeout_seconds",
        "max_input_bytes",
        "max_output_bytes"
      ],
      "properties": {
        "timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 3600
        },
        "cleanup_timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 300
        },
        "max_input_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 67108864
        },
        "max_output_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 268435456
        }
      }
    },
    "delivery_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "expected_outcome",
        "rollback_or_recovery",
        "limitations",
        "evidence_refs"
      ],
      "properties": {
        "expected_outcome": {
          "type": "string",
          "minLength": 1
        },
        "rollback_or_recovery": {
          "type": "string",
          "minLength": 1
        },
        "limitations": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "repository_order": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        }
      }
    },
    "unknown_or_limitation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "statement",
        "impact",
        "handling",
        "evidence_refs"
      ],
      "properties": {
        "statement": {
          "type": "string",
          "minLength": 1
        },
        "impact": {
          "type": "string",
          "minLength": 1
        },
        "handling": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "requested_assurance": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "band",
        "reason"
      ],
      "properties": {
        "band": {
          "enum": [
            "A0",
            "A1",
            "A2",
            "A3",
            "A4"
          ]
        },
        "reason": {
          "type": "string",
          "minLength": 1
        }
      }
    }
  }
}

{
