  "$defs": {
    "operation": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "action",
        "path",
        "reason",
        "evidence_refs",
        "implements"
      ],
      "properties": {
        "action": {
          "enum": [
            "create",
            "modify",
            "delete",
            "move"
          ]
        },
        "path": {
          "type": "string",
          "minLength": 1
        },
        "to_path": {
          "type": "string",
          "minLength": 1
        },
        "reason": {
          "type": "string",
          "minLength": 1
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "implements": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "pattern": "^(direction\\.requirement:DIRREQ-[0-9A-F]{16}|design_decisions\\[[0-9]+\\])$"
          }
        },
        "long_lived_artifact": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "artifact_id",
            "artifact_type"
          ],
          "properties": {
            "artifact_id": {
              "type": "string",
              "minLength": 1
            },
            "artifact_type": {
              "enum": [
                "adr",
                "architecture",
                "domain_model",
                "domain_alignment",
                "interface",
                "data_policy",
                "quality_policy",
                "test_policy",
                "security_policy",
                "release_policy",
                "operations_policy",
                "maintenance_policy",
                "glossary",
                "product_governance",
                "engineering_assurance"
              ]
            }
          },
          "allOf": [
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "product_governance"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^PRODUCT-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "domain_model"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^MODEL-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "architecture"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^ARCH-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "quality_policy"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^POLICY-[0-9A-F]{16}$"
                  }
                }
              }
            },
            {
              "if": {
                "properties": {
                  "artifact_type": {
                    "const": "domain_alignment"
                  }
                }
              },
              "then": {
                "properties": {
                  "artifact_id": {
                    "pattern": "^ALIGNMODEL-[0-9A-F]{16}$"
                  }
                }
              }
            }
          ]
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "action": {
                "const": "move"
              }
            }
          },
          "then": {
            "required": [
              "to_path"
            ]
          },
          "else": {
            "not": {
              "required": [
                "to_path"
              ]
            }
          }
        }
      ]
    },
    "delivery_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "expected_outcome",
        "rollback_or_recovery",
        "limitations",
        "evidence_refs"
      ],
      "properties": {
        "expected_outcome": {
          "type": "string",
          "minLength": 1
        },
        "rollback_or_recovery": {
          "type": "string",
          "minLength": 1
        },
        "limitations": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "evidence_refs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "repository_order": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        }
      }
    },
    "verification_command": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "command_id",
        "argv",
        "cwd",
        "run_kind",
        "covers",
        "reasons",
        "optional_timeout",
        "source_command_indexes",
        "approved_program"
      ],
      "properties": {
        "command_id": {
          "type": "string",
          "pattern": "^VC-[0-9]{3,}$"
        },
        "argv": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "cwd": {
          "type": "string",
          "minLength": 1
        },
        "run_kind": {
          "enum": [
            "targeted_test",
            "integration_test",
            "acceptance_test",
            "typecheck",
            "build",
            "lint",
            "manual_check",
            "full_regression"
          ]
        },
        "covers": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "reasons": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "optional_timeout": {
          "type": [
            "number",
            "null"
          ],
          "exclusiveMinimum": 0,
          "maximum": 3600
        },
        "source_command_indexes": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "integer",
            "minimum": 0
          }
        },
        "approved_program": {
          "$ref": "#/$defs/approved_program"
        },
        "case_report": {
          "$ref": "test-case-config-v1.schema.json#/$defs/bound_config"
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        },
        "input_repository_ids": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        },
        "dependency_checks": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "dependency_id",
              "kind",
              "expected_version",
              "expected_contract_sha256",
              "environment",
              "max_age_seconds"
            ],
            "properties": {
              "dependency_id": {
                "type": "string",
                "pattern": "^[A-Za-z][A-Za-z0-9._:-]{0,127}$"
              },
              "kind": {
                "enum": [
                  "service",
                  "artifact"
                ]
              },
              "expected_version": {
                "type": "string",
                "minLength": 1
              },
              "expected_contract_sha256": {
                "type": "string",
                "pattern": "^[0-9a-f]{64}$"
              },
              "environment": {
                "type": "string",
                "minLength": 1
              },
              "max_age_seconds": {
                "type": [
                  "integer",
                  "null"
                ],
                "minimum": 1,
                "maximum": 604800
              }
            }
          }
        }
      }
    },
    "external_observation_provider_plan": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "provider_plan_id",
        "scope_id",
        "language_id",
        "provider_id",
        "provider_version",
        "command",
        "materials",
        "source_globs",
        "process_policy",
        "limits"
      ],
      "properties": {
        "provider_plan_id": {
          "type": "string",
          "pattern": "^OBSPROVPLAN-[0-9A-F]{16}$"
        },
        "scope_id": {
          "type": "string",
          "pattern": "^OBSCOPE-[0-9A-F]{16}$"
        },
        "language_id": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9+.#_-]*$"
        },
        "provider_id": {
          "type": "string",
          "minLength": 1
        },
        "provider_version": {
          "type": "string",
          "minLength": 1
        },
        "command": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "materials": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/external_observation_provider_material"
          }
        },
        "source_globs": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "process_policy": {
          "$ref": "#/$defs/external_observation_process_policy"
        },
        "limits": {
          "$ref": "#/$defs/external_observation_limits"
        },
        "repository_id": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^REPO-[0-9A-F]{16}$"
        }
      }
    },
    "external_observation_provider_material": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "role",
        "path",
        "sha256",
        "command_argument_index"
      ],
      "properties": {
        "role": {
          "enum": [
            "executable",
            "entry_script",
            "config",
            "supporting_file"
          ]
        },
        "path": {
          "type": "string",
          "minLength": 1
        },
        "sha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "command_argument_index": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 0
        }
      }
    },
    "external_observation_process_policy": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "policy_id",
        "purpose",
        "forbidden_program_names"
      ],
      "properties": {
        "policy_id": {
          "type": "string",
          "pattern": "^PROCESSPOLICY-[0-9A-F]{16}$"
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "forbidden_program_names": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "external_observation_limits": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "timeout_seconds",
        "cleanup_timeout_seconds",
        "max_input_bytes",
        "max_output_bytes"
      ],
      "properties": {
        "timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 3600
        },
        "cleanup_timeout_seconds": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 300
        },
        "max_input_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 67108864
        },
        "max_output_bytes": {
          "type": "integer",
          "minimum": 1,
          "maximum": 268435456
        }
      }
    },
    "approved_program": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "declared_program",
        "resolved_program",
        "purpose",
        "argument_policy"
      ],
      "properties": {
        "declared_program": {
          "type": "string",
          "minLength": 1
        },
        "resolved_program": {
          "type": "string",
          "minLength": 1
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "argument_policy": {
          "const": "exact_plan_only"
        }
      }
    },
    "verification_policy_decision": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema_version",
        "source_kind",
        "policy_id",
        "policy_revision_id",
        "observed_commit",
        "forbidden_agent_program_names",
        "wrapper_policy",
        "working_directory_policy",
        "plan_binding_required"
      ],
      "properties": {
        "schema_version": {
          "const": "strixnova.verification-policy-decision.v1"
        },
        "source_kind": {
          "enum": [
            "project_engineering_policy",
            "confirmed_plan_bootstrap"
          ]
        },
        "policy_id": {
          "type": "string",
          "minLength": 1
        },
        "policy_revision_id": {
          "type": "string",
          "minLength": 1
        },
        "observed_commit": {
          "oneOf": [
            {
              "type": "string",
              "minLength": 1
            },
            {
              "type": "null"
            }
          ]
        },
        "forbidden_agent_program_names": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "wrapper_policy": {
          "const": "forbidden_unless_exactly_approved"
        },
        "working_directory_policy": {
          "const": "project_or_authorized_worktree_only"
        },
        "plan_binding_required": {
          "const": true
        }
      }
    },
    "domain_fact_reference": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema_version",
        "authority_kind",
        "model_id",
        "fact_id",
        "observed_commit"
      ],
      "properties": {
        "schema_version": {
          "const": "strixnova.domain-fact-reference.v1"
        },
        "authority_kind": {
          "const": "project_domain_model"
        },
        "model_id": {
          "type": "string",
          "pattern": "^MODEL-[0-9A-F]{16}$"
        },
        "fact_id": {
          "type": "string",
          "pattern": "^FACT-[0-9A-F]{16}$"
        },
        "observed_commit": {
          "type": "string",
          "pattern": "^[0-9a-f]{40,64}$"
        }
      }
    },
    "implementation_slice": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "schema_version",
        "slice_id",
        "source_slice_ref",
        "purpose",
        "implements",
        "operation_refs",
        "continued_operation_refs",
        "depends_on",
        "parallel_safe_with",
        "completion_criteria",
        "verification_command_ids",
        "rollback_or_recovery",
        "machine_validated",
        "repository_ids"
      ],
      "properties": {
        "schema_version": {
          "const": "strixnova.implementation-slice-plan.v1"
        },
        "slice_id": {
          "type": "string",
          "pattern": "^SLICE-[0-9]{3,}$"
        },
        "source_slice_ref": {
          "type": "string",
          "pattern": "^implementation_slices\\[[0-9]+\\]$"
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "implements": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "operation_refs": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^operations\\[[0-9]+\\]$"
          }
        },
        "continued_operation_refs": {
          "description": "仅用于唯一后续切片刷新同一份已计划的实现对齐草稿。",
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^operations\\[[0-9]+\\]$"
          }
        },
        "depends_on": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^SLICE-[0-9]{3,}$"
          }
        },
        "parallel_safe_with": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^SLICE-[0-9]{3,}$"
          }
        },
        "completion_criteria": {
          "type": "array",
          "minItems": 1,
          "uniqueItems": true,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "verification_command_ids": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": "string",
            "pattern": "^VC-[0-9]{3,}$"
          }
        },
        "rollback_or_recovery": {
          "type": "string",
          "minLength": 1
        },
        "machine_validated": {
          "const": true
        },
        "repository_ids": {
          "type": "array",
          "uniqueItems": true,
          "items": {
            "type": [
              "string",
              "null"
            ],
            "pattern": "^REPO-[0-9A-F]{16}$"
          }
        }
      }
    },
    "assessment_ref": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "work_item_id",
        "assessment_id",
        "assessment_revision"
      ],
      "properties": {
        "work_item_id": {
          "type": "string",
          "minLength": 1
        },
        "assessment_id": {
          "type": "string",
          "minLength": 1
        },
        "assessment_revision": {
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "direction_ref": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "work_item_id",
        "direction_version"
      ],
      "properties": {
        "work_item_id": {
          "type": "string",
          "minLength": 1
        },
        "direction_version": {
          "type": "integer",
          "minimum": 1
        }
      }
    }
  }
}

